import axios from 'axios';
import { GenerateTxCodeRequestDTO, GenerateTxCodeResponseDTO } from '~/entities/payment/api/dtos/types';
import { API_URLS } from '~/shared/api/api-urls';
import { resultify } from '~/shared/lib/utils/resultify';
import { RefundRequestDTO, RefundResponseDTO } from './dtos/refund';

export const paymentApi = {
  generateTxCode: ({ tbPayMastr }: GenerateTxCodeRequestDTO) =>
    resultify(axios.post<GenerateTxCodeResponseDTO>(API_URLS.generateTxCode, { tbPayMastr })),

  refund: ({ tbPayMastr }: RefundRequestDTO) =>
    resultify(axios.post<RefundResponseDTO>(API_URLS.refund, { tbPayMastr })),
} as const;
